def antichain_expand(current_antichain):
    next_set = set()
    for s in current_antichain:
        for succ in successors(s):
            if not comparable_to_any(succ, next_set):
                next_set.add(succ)
    return next_set

def oracle_prune(state):
    if compute_slack(state) > max_C:
        return True  # safe, prune
    return False

def exact_test(automaton, oracles):
    visited = set()
    frontier = antichain([initial_state()])
    while frontier:
        next_frontier = antichain([])
        for s in frontier:
            if oracle_prune(s, oracles): continue
            if miss_detected(s): return False
            for succ in successors(s):
                if succ not in visited:
                    next_frontier.add(succ)
        frontier = next_frontier
    return True
